html:
{#- Item sticker 80 x 30 mm, one sticker per page (thermal label roll). Layout taken from Roopa's "Sticker Print". -#}
{%- set c = label_context(doc) -%}
<meta name="pdfkit-page-width" content="80mm">
<meta name="pdfkit-page-height" content="30mm">
<meta name="pdfkit-margin-top" content="0mm">
<meta name="pdfkit-margin-bottom" content="0mm">
<meta name="pdfkit-margin-left" content="0mm">
<meta name="pdfkit-margin-right" content="0mm">
<style>
	@page { size: 80mm 30mm; margin: 0; }
	html, body { margin: 0 !important; padding: 0 !important; background: #fff; }
	.print-format { padding: 0 !important; margin: 0 !important; max-width: none !important; width: 80mm !important; min-height: 0 !important; }
	.ist { width: 80mm; height: 30mm; overflow: hidden; box-sizing: border-box; padding: 1mm 2mm;
		font-family: Arial, Helvetica, sans-serif; color: #000; page-break-after: always; break-after: page; page-break-inside: avoid; }
	.ist:last-child { page-break-after: auto; break-after: auto; }
	.ist table { width: 100%; height: 28mm; border-collapse: collapse; table-layout: fixed; }
	.ist td { padding: 0 !important; border: 0 !important; vertical-align: middle; }
	.ist-qr { width: 27mm; }
	.ist-qr div { width: 26mm; height: 26mm; }
	.ist-text { padding-left: 3mm !important; }
	.ist-f { font-size: 13px; font-weight: bold; line-height: 1.15; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
	.ist-name { font-size: 15px; font-weight: bold; text-transform: uppercase; line-height: 1.2; max-height: 2.4em; overflow: hidden; margin-bottom: 0.5mm; }
	.ist-price { font-size: 18px; font-weight: bold; margin-top: 0.5mm; white-space: nowrap; }
</style>
{%- for row in c.labels %}
{%- set item = frappe.get_cached_doc("Item", row.item_code) %}
<div class="ist"><table><tr>
	<td class="ist-qr"><div>{{ qr_svg(row.barcode) }}</div></td>
	<td class="ist-text">
		<div class="ist-f">ID: {{ row.serial_no or row.item_code }}</div>
		<div class="ist-name">{{ row.item_name }}</div>
		{%- if item.get("custom_length_mm") and item.get("custom_breadh_mm") %}
		<div class="ist-f">Size: {{ item.get("custom_length_mm") }}x{{ item.get("custom_breadh_mm") }}mm</div>
		{%- elif item.get("custom_size") %}
		<div class="ist-f">Size: {{ item.get("custom_size") }}</div>
		{%- elif row.details %}
		<div class="ist-f">{{ row.details }}</div>
		{%- endif %}
		{%- if item.get("custom_series") %}<div class="ist-f">Series: {{ item.get("custom_series") }}</div>{% endif %}
		{%- if item.get("custom_tile_finish") %}<div class="ist-f">Finish: {{ item.get("custom_tile_finish") }}</div>{% endif %}
		{%- if c.show_price and row.rate %}<div class="ist-price">MRP: {{ frappe.utils.fmt_money(row.rate, 0, c.currency) }}</div>{% endif %}
	</td>
</tr></table></div>
{%- endfor %}
